function calculateEan13CheckDigit(twelveDigits) {
  if (!/^\d{12}$/.test(twelveDigits)) {
    throw new Error('EAN-13 base must be exactly 12 numeric digits');
  }
  let sum = 0;
  for (let i = 0; i < 12; i += 1) {
    const digit = Number(twelveDigits[i]);
    sum += i % 2 === 0 ? digit : digit * 3;
  }
  const mod = sum % 10;
  return mod === 0 ? 0 : 10 - mod;
}

function makeEan13(counter) {
  const prefix = '20'; // GS1 reserved for in-store internal use
  const numStr = String(counter).padStart(10, '0');
  const base12 = `${prefix}${numStr}`;
  const check = calculateEan13CheckDigit(base12);
  return `${base12}${check}`;
}

